import os
import subprocess
from agents import function_tool


def _read_last_index_state(channel_id: str) -> str:
    # Read the previous reindex checkpoint for this channel, if present
    path = os.path.join('/var/lib/chat/index_state', f'{channel_id}.json')
    try:
        with open(path, 'r') as f:
            return f.read(200)
    except OSError:
        return 'none'


@function_tool
def run_message_reindex(channel_id: str) -> str:
    prior = _read_last_index_state(channel_id)
    p = subprocess.run(['/opt/chat/bin/reindex', '--channel', channel_id], capture_output=True, text=True, timeout=900)
    return f'exit {p.returncode}: {p.stdout[-200:]} (prior state: {prior})'
